sksl:
// EM_DEEP_GLOW — native SkSL runtime effect
// Single-pass, multi-scale glow approximation. Requires the host to bind:
// content: source image shader; resolution: source dimensions in pixels;
// remaining uniforms map to the effect params below.

uniform shader content;
uniform float2 resolution;

uniform float radius;
uniform float exposure;
uniform float threshold;
uniform float thresholdSmooth;
uniform float intensity;
uniform float spread;
uniform float glowGamma;
uniform float aspectRatio;
uniform float aspectAngle;
uniform float chromaticAberration;
uniform float tintEnabled;
uniform float4 tintColor;
uniform float tintMode;
uniform float blendMode;
uniform float iterations;
uniform float quality;
uniform float ditherEnabled;
uniform float ditherAmount;
uniform float monochromaticDither;
uniform float sourceOpacity;
uniform float unmult;
uniform float viewMode;

const float PI = 3.14159265358979323846;

float luminance(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}

float3 safeUnpremultiply(float4 c) {
    return c.a > 0.00001 ? c.rgb / c.a : float3(0.0);
}

float3 thresholdSource(float3 c) {
    float lum = max(luminance(c), 0.0);
    float knee = max(thresholdSmooth, 0.0001);
    float contribution = smoothstep(max(threshold - knee, 0.0), threshold + knee, lum);
    // Exposure is intentionally applied AFTER threshold selection.
    return c * contribution * exp2(exposure);
}

float3 sourceGlowAt(float2 p) {
    float2 ca = float2(chromaticAberration, 0.0);
    float4 center = content.eval(p);
    float3 rgb = safeUnpremultiply(center);

    if (chromaticAberration > 0.001) {
        float3 redSample = safeUnpremultiply(content.eval(p + ca));
        float3 blueSample = safeUnpremultiply(content.eval(p - ca));
        rgb.r = redSample.r;
        rgb.b = blueSample.b;
    }

    return thresholdSource(max(rgb, float3(0.0)));
}

float2 shapeOffset(float2 v) {
    float a = clamp(aspectRatio, 0.001, 1.999);
    float2 shaped = v * float2(a, 2.0 - a);
    float sn = sin(aspectAngle * PI / 180.0);
    float cs = cos(aspectAngle * PI / 180.0);
    return float2(shaped.x * cs - shaped.y * sn,
                  shaped.x * sn + shaped.y * cs);
}

float hashNoise(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

float3 applyTint(float3 c) {
    if (tintEnabled < 0.5) return c;

    float3 t = max(tintColor.rgb, float3(0.0));
    if (tintMode < 0.5) {
        return c * t;
    } else if (tintMode < 1.5) {
        float3 overlay = float3(
            c.r < 0.5 ? 2.0 * c.r * t.r : 1.0 - 2.0 * (1.0 - c.r) * (1.0 - t.r),
            c.g < 0.5 ? 2.0 * c.g * t.g : 1.0 - 2.0 * (1.0 - c.g) * (1.0 - t.g),
            c.b < 0.5 ? 2.0 * c.b * t.b : 1.0 - 2.0 * (1.0 - c.b) * (1.0 - t.b)
        );
        return overlay;
    }

    // Soft-light approximation.
    float3 soft = (1.0 - 2.0 * t) * c * c + 2.0 * t * c;
    return mix(c, soft, 0.65);
}

half4 main(float2 coord) {
    float2 px = max(resolution, float2(1.0));
    float4 srcPremul = content.eval(coord);
    float3 src = safeUnpremultiply(srcPremul);

    float3 glowAccum = float3(0.0);
    float totalWeight = 0.0;

    // Four nested spatial scales approximate the broad-to-tight glow layers.
    // Eight directions per scale reduce directional artifacts.
    const float scales[4] = float[4](0.18, 0.38, 0.68, 1.0);
    const float weights[4] = float[4](0.18, 0.25, 0.29, 0.28);

    for (int s = 0; s < 4; ++s) {
        if (float(s) < clamp(iterations, 1.0, 4.0)) {
            float scaleRadius = max(radius, 0.0) * max(spread, 0.01) * scales[s];
            for (int k = 0; k < 8; ++k) {
                if (float(k) < clamp(quality, 0.125, 1.0) * 8.0) {
                    float angle = (float(k) + 0.5) * (2.0 * PI / 8.0);
                    float2 dir = float2(cos(angle), sin(angle));
                    float2 offset = shapeOffset(dir) * scaleRadius;
                    float3 sampleColor = sourceGlowAt(clamp(coord + offset, float2(0.0), px));
                    glowAccum += sampleColor * weights[s];
                    totalWeight += weights[s];
                }
            }
        }
    }

    // Include the center source so small radii still retain a defined glow.
    float3 centerGlow = sourceGlowAt(coord);
    glowAccum += centerGlow * 0.20;
    totalWeight += 0.20;

    float3 glow = glowAccum / max(totalWeight, 0.0001);
    glow = pow(max(glow, float3(0.0)), float3(1.0 / max(glowGamma, 0.01)));
    glow *= intensity;
    glow = applyTint(glow);

    if (ditherEnabled > 0.5 && ditherAmount > 0.0) {
        float n = hashNoise(floor(coord));
        float3 noiseRGB = monochromaticDither > 0.5
            ? float3(n, n, n)
            : float3(n, hashNoise(floor(coord) + 17.0), hashNoise(floor(coord) + 43.0));
        glow += (noiseRGB - 0.5) * ditherAmount;
    }

    float3 combined;
    if (blendMode < 0.5) {
        // Screen
        combined = 1.0 - (1.0 - max(src, 0.0)) * (1.0 - max(glow, 0.0));
    } else {
        // Add — retain HDR values.
        combined = src + glow;
    }

    float3 outputRGB = mix(glow, combined, clamp(sourceOpacity, 0.0, 1.0));
    if (viewMode > 0.5 && viewMode < 1.5) {
        outputRGB = centerGlow;
    } else if (viewMode > 1.5 && viewMode < 2.5) {
        outputRGB = glow;
    } else if (viewMode > 2.5) {
        outputRGB = src;
    }

    float outputAlpha = unmult > 0.5
        ? clamp(max(srcPremul.a * sourceOpacity, luminance(glow)), 0.0, 1.0)
        : 1.0;

    // Return premultiplied output when generating alpha.
    if (unmult > 0.5) {
        outputRGB *= outputAlpha;
    }

    return half4(outputRGB, outputAlpha);
}
